/*
  Migracion 19 - Textos faltantes de los idiomas cargados (incluye la pantalla Instalacion).

  - Completa la tabla TraduccionTable con todas las claves de los resx (es, en, pt y de) para los idiomas
    que ya existen en IdiomaTable. Inserta solo lo que falta: no pisa ni modifica ningun texto existente
    (ni los editados a mano), y un idioma que no esta cargado se omite.
  - Incluye app_instalacion y descargas_* (pantalla Descargas) y los textos nuevos de Idiomas (crear idioma desde cero).
  - Despues de ejecutarla hay que reiniciar la aplicacion: el catalogo de traducciones se guarda en memoria.

  Idempotente, en una sola transaccion, sin BOM y en ASCII.
  No toca IntegridadTable: TraduccionTable no esta bajo control de integridad.
*/
USE [FalkeDB];
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @textos TABLE (codigo_idioma varchar(10), clave varchar(100), texto nvarchar(500));








    SELECT x.clave, i.id_idioma, x.texto, 0, 'resx'
    FROM @textos x
    INNER JOIN dbo.IdiomaTable i ON i.codigo_idioma = x.codigo_idioma
    WHERE NOT EXISTS (SELECT 1 FROM dbo.TraduccionTable t
                      WHERE t.codigo_clave_traduccion = x.clave AND t.id_idioma = i.id_idioma);

    PRINT CONCAT('Textos agregados: ', @@ROWCOUNT);

    COMMIT TRANSACTION;

    SELECT i.codigo_idioma, COUNT(*) AS textos
    FROM dbo.TraduccionTable t
    INNER JOIN dbo.IdiomaTable i ON i.id_idioma = t.id_idioma
    GROUP BY i.codigo_idioma
    ORDER BY i.codigo_idioma;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
