        ('es', 'faq_cuanto_tarda_desde_que_firmo_hasta', NCHAR(191) + N'Cu' + NCHAR(225) + N'nto tarda desde que firmo hasta que puedo grabar?'),
        ('es', 'faq_cuanto_tarda_el_procesamiento', NCHAR(191) + N'Cu' + NCHAR(225) + N'nto tarda el procesamiento?'),
