        ('es', 'ingresar_analitica_conductual_biometrica_por_segu', N'Anal' + NCHAR(237) + N'tica conductual biom' + NCHAR(233) + N'trica por seguimiento ocular, con hardware de precisi' + NCHAR(243) + N'n profesional incluido en la suscripci' + NCHAR(243) + N'n.'),
        ('es', 'ingresar_asi_se_obtiene_una_cuenta', N'As' + NCHAR(237) + N' se obtiene una cuenta'),
