        ('es', 'ingresar_cierre_clave_cambiada', N'Tu sesi' + NCHAR(243) + N'n se cerr' + NCHAR(243) + N' porque se cambi' + NCHAR(243) + N' la contrase' + NCHAR(241) + N'a de tu cuenta. Volv' + NCHAR(233) + N' a entrar con la nueva.'),
        ('es', 'ingresar_cierre_cuenta', N'Tu sesi' + NCHAR(243) + N'n se cerr' + NCHAR(243) + N' porque la cuenta fue dada de baja, bloqueada o cambi' + NCHAR(243) + N' de estado. Comun' + NCHAR(237) + N'cate con el administrador de tu empresa.'),
        ('es', 'ingresar_cierre_empresa_baja', N'Tu sesi' + NCHAR(243) + N'n se cerr' + NCHAR(243) + N' porque la empresa de tu cuenta fue dada de baja. Si crees que es un error, comun' + NCHAR(237) + N'cate con Pattern Blue.'),
        ('es', 'ingresar_cierre_empresa_bloqueada', N'Tu sesi' + NCHAR(243) + N'n se cerr' + NCHAR(243) + N' porque la empresa de tu cuenta fue bloqueada. Comun' + NCHAR(237) + N'cate con Pattern Blue para regularizar la situaci' + NCHAR(243) + N'n.'),
        ('es', 'ingresar_cierre_restauracion', N'Se restaur' + NCHAR(243) + N' la base de datos desde una copia de seguridad y se cerraron todas las sesiones. Volv' + NCHAR(233) + N' a entrar.'),
        ('es', 'ingresar_completar_datos', N'Completa el correo y la contrase' + NCHAR(241) + N'a para continuar.'),
