        ('es', 'ingresar_cuenta_baja', N'La cuenta fue dada de baja. Si crees que es un error, comun' + NCHAR(237) + N'cate con el administrador de tu empresa.'),
        ('es', 'ingresar_cuenta_bloqueada', N'La cuenta est' + NCHAR(225) + N' bloqueada por contrase' + NCHAR(241) + N'as incorrectas. Usa ' + NCHAR(171) + N'Olvid' + NCHAR(233) + N' mi contrase' + NCHAR(241) + N'a' + NCHAR(187) + N' para recuperar el acceso.'),
        ('es', 'ingresar_cuenta_pendiente', N'La cuenta todav' + NCHAR(237) + N'a no fue activada. Revisa el correo con el enlace de activaci' + NCHAR(243) + N'n.'),
        ('es', 'ingresar_datos_biometricos_disociados_y_cifrados', N'Datos biom' + NCHAR(233) + N'tricos disociados y cifrados'),
