    INSERT INTO @textos (codigo_idioma, clave, texto) VALUES
        ('en', 'empresas_estas_modificando_los_datos_de_un', N'You are modifying a client''s details:'),
        ('en', 'empresas_esto_afecta_a_todos_los_usuarios', N'This affects all the users of the company.'),
        ('en', 'empresas_filtrar_por_estado', N'Filter by status'),
        ('en', 'empresas_lo_que_cambies_lo_ve_la', N'The company sees whatever you change in "My company". Changing the CUIT, the plan or the billing affects invoicing. It is recorded in the audit log and the company sees it as done by the Pattern Blue team.'),
        ('en', 'empresas_no_hay_empresas_que_coincidan', N'No companies match.'),
        ('en', 'empresas_nueva_empresa', N'New company'),
        ('en', 'empresas_obligatorio_si_cambia_la_razon_social', N'(required if the legal name, the CUIT or the plan changes)'),
        ('en', 'empresas_razon_social_cuit_o_rubro', N'Legal name, CUIT or industry...'),
        ('en', 'empresas_telefono_de_contacto', N'Contact phone'),
        ('en', 'empresas_todas', N'All'),
        ('en', 'empresas_usuarios_totales', N'Total users'),
        ('en', 'faq_arranca_solo_al_terminar_la_grabacion', N'It starts automatically when the recording ends and, under normal load, makes all the visualizations available in under five minutes. There is no manual step on your side.'),
        ('en', 'faq_buscar_en_las_preguntas_frecuentes', N'Search the frequently asked questions'),
        ('en', 'faq_buscar_una_pregunta', N'Search for a question...'),
        ('en', 'faq_contratacion', N'Hiring'),
        ('en', 'faq_contratacion_y_facturacion', N'Hiring and billing'),
        ('en', 'faq_conviene_pagar_por_mes_o_por', N'Is it better to pay monthly or yearly?'),
        ('en', 'faq_cuanto_tarda_desde_que_firmo_hasta', N'How long does it take from signing until I can record?'),
        ('en', 'faq_cuanto_tarda_el_procesamiento', N'How long does processing take?'),
        ('en', 'faq_datos_y_seguridad', N'Data and security'),
        ('en', 'faq_donde_se_guardan_las_grabaciones', N'Where are the recordings stored?'),
        ('en', 'faq_el_administrador_de_tu_empresa_ve', N'Your company''s administrator sees the audit log of the actions of the users of your own organization, and nothing else. Analyses and recordings are only accessible to the users of your account.'),
        ('en', 'faq_el_dispositivo_vuelve_a_pattern_blue', N'The device goes back to Pattern Blue at no cost to you, reusing the same packaging it arrived in. We notify you by email in advance and arrange the pickup.'),
        ('en', 'faq_el_objetivo_es_que_puedas_correr', N'The goal is for you to run your first session within ten days of the contract being signed, including the shipping of the device. In AMBA, C' + NCHAR(243) + N'rdoba, Rosario and Mendoza this deadline is met without problems; for other locations it is agreed case by case.'),
        ('en', 'faq_el_pago_anual_anticipado_tiene_un', N'Annual prepaid payment has a 20% discount over the monthly price. If you are just evaluating the tool, the monthly cycle gives you more flexibility.'),
        ('en', 'faq_el_servicio', N'The service'),
        ('en', 'faq_en_la_infraestructura_propia_de_pattern', N'On Pattern Blue''s own infrastructure, never on third-party platforms. Each company''s data is stored separately, with no possibility of cross access, and communications between your browser and the server travel encrypted.'),
        ('en', 'faq_en_que_idiomas_esta_la_plataforma', N'What languages is the platform available in?'),
        ('en', 'faq_en_que_se_diferencia_del_eye', N'How is it different from webcam eye tracking?'),
        ('en', 'faq_es_una_suite_de_analitica_conductual', N'It is a behavioral analytics suite based on eye tracking. A Tobii device records where your user looks while using your digital product, and the platform turns that data into heat maps, areas of interest, gaze paths and attention metrics ready to interpret.'),
        ('en', 'faq_escribenos_desde_la_pantalla_de_planes', N'Write to us from the plans screen and we''ll answer shortly.'),
        ('en', 'faq_espanol_ingles_y_portugues_cada_usuario', N'Spanish, English and Portuguese. Each user chooses theirs from their profile and the preference is kept between sessions, without affecting the rest of the team.'),
        ('en', 'faq_falke_usa_hardware_de_infrarrojo_dedicad', N'Falke uses dedicated infrared hardware, not the computer''s webcam. This gives higher accuracy and is not affected by the participant''s posture or lighting. We also impose no limit on duration or asset type: you can analyze a video game or a complete software flow.'),
        ('en', 'faq_hardware_y_soporte', N'Hardware and support'),
        ('en', 'faq_hay_limite_de_duracion_en_las', N'Is there a limit on session duration?'),
        ('en', 'faq_ir_a_los_planes', N'Go to the plans'),
        ('en', 'faq_los_datos_de_seguimiento_ocular_se', N'Eye tracking data is dissociated from the tester''s identity at the moment it is saved: what remains stored does not allow the person to be identified. It is a requirement of Law No. 25,326 on Personal Data Protection and is considered from the design of the system.'),
        ('en', 'faq_no_el_modelo_de_falke_esta', N'No. Falke''s model is designed so that you work with your own users, in your own environment. This gives much more fidelity than an external panel, especially for products with specific audiences. We also don''t do design consulting: we deliver the evidence, the decision is up to your team.'),
        ('en', 'faq_no_encontramos_ninguna_pregunta_con_ese', N'We couldn''t find any question with that text. Try other words.'),
        ('en', 'faq_no_puedes_grabar_una_sesion_tan', N'No. You can record a session as long as you need, which is precisely what makes it possible to analyze video games or complete business software flows.'),
        ('en', 'faq_por_que_no_puedo_crear_una', N'Why can''t I create an account on my own?'),
        ('en', 'faq_porque_el_servicio_incluye_un_dispositiv', N'Because the service includes a physical device on loan. The registration is done by a Pattern Blue manager once the contract is signed: the company is registered, the administrator user is created and that person receives an email with a link to set their password. From there the administrator invites the rest of their team.'),
        ('en', 'faq_preguntas_frecuentes', N'Frequently asked questions'),
        ('en', 'faq_puedo_combinar_varias_sesiones_en_un', N'Can I combine several sessions into one analysis?'),
        ('en', 'faq_puedo_compartir_los_resultados_con_gente', N'Can I share the results with people who don''t have an account?'),
        ('en', 'faq_que_es_exactamente_falke', N'What exactly is Falke?'),
        ('en', 'faq_que_necesito_en_mi_equipo', N'What do I need on my computer?'),
        ('en', 'faq_que_pasa_con_los_datos_de', N'What happens to the data of the people who participate?'),
        ('en', 'faq_que_pasa_cuando_termina_el_contrato', N'What happens when the contract ends?'),
        ('en', 'faq_que_tipos_de_activos_digitales_puedo', N'What types of digital assets can I analyze?'),
        ('en', 'faq_que_visualizaciones_obtengo_de_cada_sesi', N'What visualizations do I get from each session?'),
        ('en', 'faq_quien_puede_ver_lo_que_hace', N'Who can see what my team does?'),
        ('en', 'faq_seis_la_grabacion_con_el_seguimiento', N'Six: the recording with the tracking overlaid, the heat map, areas of interest and blind spots, gaze dispersion, gaze path and the attention vs. distraction ratio. Plus the statistical metrics: duration, number of fixations and mean fixation time.'),
        ('en', 'faq_si_cada_analisis_se_exporta_a', N'Yes. Each analysis is exported to PDF by choosing with checkboxes which visualizations and metrics to include. That report can be shared with anyone, without them needing to enter the platform.'),
        ('en', 'faq_si_con_el_analisis_multiple_planes', N'Yes, with multiple analysis (Hunter and Apex plans). The data of several sessions is averaged to see common patterns across different testers. The platform validates that all sessions are of the same asset type, because otherwise the average would not be valid.'),
        ('en', 'faq_si_la_falla_no_es_atribuible', N'If the failure is not attributable to use, repair or replacement is at Pattern Blue''s expense, at no additional cost. Damage from impacts, liquids, unauthorized modifications or loss is excluded.'),
        ('en', 'faq_sobre_el_servicio', N'About the service'),
        ('en', 'faq_software_de_escritorio_aplicaciones_web', N'Desktop software, web apps, mobile apps, video games and digital advertising pieces. When you create the category you choose the type, and the platform asks for the data specific to that case (operating system, platform, distribution channel, etc.).'),
        ('en', 'faq_te_quedo_alguna_duda', N'Still have a question?'),
        ('en', 'faq_todo_lo_que_suelen_preguntarnos_antes', N'Everything we are usually asked before hiring Falke. If you still have a question, write to us and we''ll answer it.'),
        ('en', 'faq_un_equipo_de_oficina_estandar_con', N'A standard office computer with a free USB port, an up-to-date browser (Chrome, Firefox or Edge) and the Tobii device driver installed. The platform checks the connection, the calibration and the driver version before letting you start a recording.'),
        ('en', 'faq_uso_de_la_plataforma', N'Using the platform'),
