        ('pt', 'faq_el_administrador_de_tu_empresa_ve', N'O administrador da sua empresa v' + NCHAR(234) + N' o registro de auditoria das a' + NCHAR(231) + NCHAR(245) + N'es dos usu' + NCHAR(225) + N'rios da sua pr' + NCHAR(243) + N'pria organiza' + NCHAR(231) + NCHAR(227) + N'o, e nada mais. As an' + NCHAR(225) + N'lises e grava' + NCHAR(231) + NCHAR(245) + N'es s' + NCHAR(243) + N' s' + NCHAR(227) + N'o acess' + NCHAR(237) + N'veis aos usu' + NCHAR(225) + N'rios da sua conta.'),
        ('pt', 'faq_el_dispositivo_vuelve_a_pattern_blue', N'O dispositivo volta para a Pattern Blue sem custo para voc' + NCHAR(234) + N', reutilizando a mesma embalagem em que chegou. Avisamos voc' + NCHAR(234) + N' por e-mail com anteced' + NCHAR(234) + N'ncia e combinamos a retirada.'),
        ('pt', 'faq_el_objetivo_es_que_puedas_correr', N'O objetivo ' + NCHAR(233) + N' que voc' + NCHAR(234) + N' execute sua primeira sess' + NCHAR(227) + N'o em at' + NCHAR(233) + N' dez dias ap' + NCHAR(243) + N's a assinatura do contrato, incluindo o envio do dispositivo. Na AMBA, C' + NCHAR(243) + N'rdoba, Rosario e Mendoza esse prazo ' + NCHAR(233) + N' cumprido sem problemas; para outras localidades ' + NCHAR(233) + N' combinado caso a caso.'),
        ('pt', 'faq_el_pago_anual_anticipado_tiene_un', N'O pagamento anual antecipado tem 20% de desconto sobre o pre' + NCHAR(231) + N'o mensal. Se voc' + NCHAR(234) + N' est' + NCHAR(225) + N' apenas avaliando a ferramenta, o ciclo mensal d' + NCHAR(225) + N' mais flexibilidade.'),
        ('pt', 'faq_el_servicio', N'O servi' + NCHAR(231) + N'o'),
        ('pt', 'faq_en_la_infraestructura_propia_de_pattern', N'Na infraestrutura pr' + NCHAR(243) + N'pria da Pattern Blue, nunca em plataformas de terceiros. Os dados de cada empresa s' + NCHAR(227) + N'o armazenados separadamente, sem possibilidade de acesso cruzado, e as comunica' + NCHAR(231) + NCHAR(245) + N'es entre o seu navegador e o servidor trafegam criptografadas.'),
        ('pt', 'faq_en_que_idiomas_esta_la_plataforma', N'Em quais idiomas a plataforma est' + NCHAR(225) + N' dispon' + NCHAR(237) + N'vel?'),
        ('pt', 'faq_en_que_se_diferencia_del_eye', N'Qual a diferen' + NCHAR(231) + N'a em rela' + NCHAR(231) + NCHAR(227) + N'o ao eye tracking por webcam?'),
        ('pt', 'faq_es_una_suite_de_analitica_conductual', NCHAR(201) + N' uma su' + NCHAR(237) + N'te de an' + NCHAR(225) + N'lise comportamental baseada em eye tracking. Um dispositivo Tobii registra para onde o seu usu' + NCHAR(225) + N'rio olha ao usar o seu produto digital, e a plataforma transforma esses dados em mapas de calor, ' + NCHAR(225) + N'reas de interesse, trajet' + NCHAR(243) + N'rias do olhar e m' + NCHAR(233) + N'tricas de aten' + NCHAR(231) + NCHAR(227) + N'o prontas para interpretar.'),
        ('pt', 'faq_escribenos_desde_la_pantalla_de_planes', N'Escreva para n' + NCHAR(243) + N's na tela de planos e responderemos em breve.'),
        ('pt', 'faq_espanol_ingles_y_portugues_cada_usuario', N'Espanhol, ingl' + NCHAR(234) + N's e portugu' + NCHAR(234) + N's. Cada usu' + NCHAR(225) + N'rio escolhe o seu no perfil e a prefer' + NCHAR(234) + N'ncia ' + NCHAR(233) + N' mantida entre sess' + NCHAR(245) + N'es, sem afetar o restante da equipe.'),
        ('pt', 'faq_falke_usa_hardware_de_infrarrojo_dedicad', N'O Falke usa hardware infravermelho dedicado, n' + NCHAR(227) + N'o a webcam do computador. Isso d' + NCHAR(225) + N' mais precis' + NCHAR(227) + N'o e n' + NCHAR(227) + N'o ' + NCHAR(233) + N' afetado pela postura nem pela ilumina' + NCHAR(231) + NCHAR(227) + N'o do participante. Tamb' + NCHAR(233) + N'm n' + NCHAR(227) + N'o impomos limite de dura' + NCHAR(231) + NCHAR(227) + N'o nem de tipo de ativo: voc' + NCHAR(234) + N' pode analisar um videogame ou um fluxo completo de software.'),
        ('pt', 'faq_hardware_y_soporte', N'Hardware e suporte'),
        ('pt', 'faq_hay_limite_de_duracion_en_las', N'Existe limite de dura' + NCHAR(231) + NCHAR(227) + N'o das sess' + NCHAR(245) + N'es?'),
        ('pt', 'faq_ir_a_los_planes', N'Ir para os planos'),
        ('pt', 'faq_los_datos_de_seguimiento_ocular_se', N'Os dados de eye tracking s' + NCHAR(227) + N'o dissociados da identidade do testador no momento em que s' + NCHAR(227) + N'o salvos: o que fica armazenado n' + NCHAR(227) + N'o permite identificar a pessoa. ' + NCHAR(201) + N' um requisito da Lei n' + NCHAR(186) + N' 25.326 de Prote' + NCHAR(231) + NCHAR(227) + N'o de Dados Pessoais e ' + NCHAR(233) + N' considerado desde o projeto do sistema.'),
        ('pt', 'faq_no_el_modelo_de_falke_esta', N'N' + NCHAR(227) + N'o. O modelo do Falke foi pensado para que voc' + NCHAR(234) + N' trabalhe com os seus pr' + NCHAR(243) + N'prios usu' + NCHAR(225) + N'rios, no seu pr' + NCHAR(243) + N'prio ambiente. Isso d' + NCHAR(225) + N' muito mais fidelidade do que um painel externo, especialmente para produtos com p' + NCHAR(250) + N'blicos espec' + NCHAR(237) + N'ficos. Tamb' + NCHAR(233) + N'm n' + NCHAR(227) + N'o fazemos consultoria de design: entregamos a evid' + NCHAR(234) + N'ncia, a decis' + NCHAR(227) + N'o ' + NCHAR(233) + N' da sua equipe.'),
        ('pt', 'faq_no_encontramos_ninguna_pregunta_con_ese', N'N' + NCHAR(227) + N'o encontramos nenhuma pergunta com esse texto. Tente outras palavras.'),
        ('pt', 'faq_no_puedes_grabar_una_sesion_tan', N'N' + NCHAR(227) + N'o. Voc' + NCHAR(234) + N' pode gravar uma sess' + NCHAR(227) + N'o pelo tempo que precisar, e ' + NCHAR(233) + N' justamente isso que permite analisar videogames ou fluxos completos de software empresarial.'),
        ('pt', 'faq_por_que_no_puedo_crear_una', N'Por que n' + NCHAR(227) + N'o posso criar uma conta por conta pr' + NCHAR(243) + N'pria?'),
        ('pt', 'faq_porque_el_servicio_incluye_un_dispositiv', N'Porque o servi' + NCHAR(231) + N'o inclui um dispositivo f' + NCHAR(237) + N'sico em comodato. O cadastro ' + NCHAR(233) + N' feito por um gerente da Pattern Blue depois da assinatura do contrato: a empresa ' + NCHAR(233) + N' cadastrada, o usu' + NCHAR(225) + N'rio administrador ' + NCHAR(233) + N' criado e essa pessoa recebe um e-mail com um link para definir a senha. A partir da' + NCHAR(237) + N', o administrador convida o resto da equipe.'),
        ('pt', 'faq_preguntas_frecuentes', N'Perguntas frequentes'),
        ('pt', 'faq_puedo_combinar_varias_sesiones_en_un', N'Posso combinar v' + NCHAR(225) + N'rias sess' + NCHAR(245) + N'es em uma an' + NCHAR(225) + N'lise?'),
        ('pt', 'faq_puedo_compartir_los_resultados_con_gente', N'Posso compartilhar os resultados com pessoas que n' + NCHAR(227) + N'o t' + NCHAR(234) + N'm conta?'),
        ('pt', 'faq_que_es_exactamente_falke', N'O que exatamente ' + NCHAR(233) + N' o Falke?'),
        ('pt', 'faq_que_necesito_en_mi_equipo', N'O que preciso no meu computador?'),
        ('pt', 'faq_que_pasa_con_los_datos_de', N'O que acontece com os dados das pessoas que participam?'),
