        ('pt', 'faq_que_visualizaciones_obtengo_de_cada_sesi', N'Quais visualiza' + NCHAR(231) + NCHAR(245) + N'es recebo de cada sess' + NCHAR(227) + N'o?'),
        ('pt', 'faq_quien_puede_ver_lo_que_hace', N'Quem pode ver o que a minha equipe faz?'),
        ('pt', 'faq_seis_la_grabacion_con_el_seguimiento', N'Seis: a grava' + NCHAR(231) + NCHAR(227) + N'o com o rastreamento sobreposto, o mapa de calor, ' + NCHAR(225) + N'reas de interesse e pontos cegos, dispers' + NCHAR(227) + N'o do olhar, trajet' + NCHAR(243) + N'ria do olhar e a rela' + NCHAR(231) + NCHAR(227) + N'o aten' + NCHAR(231) + NCHAR(227) + N'o vs. distra' + NCHAR(231) + NCHAR(227) + N'o. Al' + NCHAR(233) + N'm das m' + NCHAR(233) + N'tricas estat' + NCHAR(237) + N'sticas: dura' + NCHAR(231) + NCHAR(227) + N'o, n' + NCHAR(250) + N'mero de fixa' + NCHAR(231) + NCHAR(245) + N'es e tempo m' + NCHAR(233) + N'dio de fixa' + NCHAR(231) + NCHAR(227) + N'o.'),
        ('pt', 'faq_si_cada_analisis_se_exporta_a', N'Sim. Cada an' + NCHAR(225) + N'lise ' + NCHAR(233) + N' exportada em PDF escolhendo, com caixas de sele' + NCHAR(231) + NCHAR(227) + N'o, quais visualiza' + NCHAR(231) + NCHAR(245) + N'es e m' + NCHAR(233) + N'tricas incluir. Esse relat' + NCHAR(243) + N'rio pode ser compartilhado com qualquer pessoa, sem que ela precise entrar na plataforma.'),
        ('pt', 'faq_si_con_el_analisis_multiple_planes', N'Sim, com a an' + NCHAR(225) + N'lise m' + NCHAR(250) + N'ltipla (planos Hunter e Apex). Os dados de v' + NCHAR(225) + N'rias sess' + NCHAR(245) + N'es s' + NCHAR(227) + N'o promediados para ver padr' + NCHAR(245) + N'es comuns entre diferentes testadores. A plataforma valida que todas as sess' + NCHAR(245) + N'es s' + NCHAR(227) + N'o do mesmo tipo de ativo, porque do contr' + NCHAR(225) + N'rio a m' + NCHAR(233) + N'dia n' + NCHAR(227) + N'o seria v' + NCHAR(225) + N'lida.'),
        ('pt', 'faq_si_la_falla_no_es_atribuible', N'Se a falha n' + NCHAR(227) + N'o for atribu' + NCHAR(237) + N'vel ao uso, o reparo ou a substitui' + NCHAR(231) + NCHAR(227) + N'o ' + NCHAR(233) + N' por conta da Pattern Blue, sem custo adicional. Ficam exclu' + NCHAR(237) + N'dos danos por impactos, l' + NCHAR(237) + N'quidos, modifica' + NCHAR(231) + NCHAR(245) + N'es n' + NCHAR(227) + N'o autorizadas ou perda.'),
        ('pt', 'faq_sobre_el_servicio', N'Sobre o servi' + NCHAR(231) + N'o'),
        ('pt', 'faq_software_de_escritorio_aplicaciones_web', N'Software de desktop, apps web, apps mobile, videogames e pe' + NCHAR(231) + N'as de publicidade digital. Ao criar a categoria, voc' + NCHAR(234) + N' escolhe o tipo, e a plataforma pede os dados espec' + NCHAR(237) + N'ficos para esse caso (sistema operacional, plataforma, canal de distribui' + NCHAR(231) + NCHAR(227) + N'o etc.).'),
        ('pt', 'faq_te_quedo_alguna_duda', N'Ainda tem d' + NCHAR(250) + N'vidas?'),
        ('pt', 'faq_todo_lo_que_suelen_preguntarnos_antes', N'Tudo o que costumam nos perguntar antes de contratar o Falke. Se ainda tiver alguma d' + NCHAR(250) + N'vida, escreva para n' + NCHAR(243) + N's e responderemos.'),
        ('pt', 'faq_un_equipo_de_oficina_estandar_con', N'Um computador de escrit' + NCHAR(243) + N'rio padr' + NCHAR(227) + N'o com uma porta USB livre, um navegador atualizado (Chrome, Firefox ou Edge) e o driver do dispositivo Tobii instalado. A plataforma verifica a conex' + NCHAR(227) + N'o, a calibra' + NCHAR(231) + NCHAR(227) + N'o e a vers' + NCHAR(227) + N'o do driver antes de deixar voc' + NCHAR(234) + N' iniciar uma grava' + NCHAR(231) + NCHAR(227) + N'o.'),
        ('pt', 'faq_uso_de_la_plataforma', N'Uso da plataforma'),
