        ('de', 'empresas_todas', N'Alle'),
        ('de', 'empresas_usuarios_totales', N'Benutzer insgesamt'),
        ('de', 'faq_arranca_solo_al_terminar_la_grabacion', N'Sie startet automatisch, wenn die Aufnahme endet, und stellt unter normaler Last alle Visualisierungen in weniger als f' + NCHAR(252) + N'nf Minuten bereit. Auf Ihrer Seite ist kein manueller Schritt n' + NCHAR(246) + N'tig.'),
        ('de', 'faq_buscar_en_las_preguntas_frecuentes', N'H' + NCHAR(228) + N'ufig gestellte Fragen durchsuchen'),
        ('de', 'faq_buscar_una_pregunta', N'Nach einer Frage suchen...'),
        ('de', 'faq_contratacion', N'Beauftragung'),
        ('de', 'faq_contratacion_y_facturacion', N'Beauftragung und Abrechnung'),
        ('de', 'faq_conviene_pagar_por_mes_o_por', N'Ist es besser, monatlich oder j' + NCHAR(228) + N'hrlich zu zahlen?'),
        ('de', 'faq_cuanto_tarda_desde_que_firmo_hasta', N'Wie lange dauert es von der Unterschrift, bis ich aufnehmen kann?'),
        ('de', 'faq_cuanto_tarda_el_procesamiento', N'Wie lange dauert die Verarbeitung?'),
        ('de', 'faq_datos_y_seguridad', N'Daten und Sicherheit'),
        ('de', 'faq_donde_se_guardan_las_grabaciones', N'Wo werden die Aufnahmen gespeichert?'),
        ('de', 'faq_el_administrador_de_tu_empresa_ve', N'Der Administrator Ihres Unternehmens sieht das Audit-Protokoll der Aktionen der Benutzer Ihrer eigenen Organisation und sonst nichts. Analysen und Aufnahmen sind nur f' + NCHAR(252) + N'r die Benutzer Ihres Kontos zug' + NCHAR(228) + N'nglich.'),
        ('de', 'faq_el_dispositivo_vuelve_a_pattern_blue', N'Das Ger' + NCHAR(228) + N't geht f' + NCHAR(252) + N'r Sie kostenlos an Pattern Blue zur' + NCHAR(252) + N'ck, in derselben Verpackung, in der es angekommen ist. Wir benachrichtigen Sie vorab per E-Mail und vereinbaren die Abholung.'),
        ('de', 'faq_el_objetivo_es_que_puedas_correr', N'Ziel ist, dass Sie Ihre erste Sitzung innerhalb von zehn Tagen nach Vertragsabschluss durchf' + NCHAR(252) + N'hren, einschlie' + NCHAR(223) + N'lich des Versands des Ger' + NCHAR(228) + N'ts. In AMBA, C' + NCHAR(243) + N'rdoba, Rosario und Mendoza wird diese Frist problemlos eingehalten; f' + NCHAR(252) + N'r andere Orte wird sie im Einzelfall vereinbart.'),
        ('de', 'faq_el_pago_anual_anticipado_tiene_un', N'Die j' + NCHAR(228) + N'hrliche Vorauszahlung bietet 20 % Rabatt auf den Monatspreis. Wenn Sie das Tool nur evaluieren, bietet der Monatszyklus mehr Flexibilit' + NCHAR(228) + N't.'),
        ('de', 'faq_el_servicio', N'Der Dienst'),
        ('de', 'faq_en_la_infraestructura_propia_de_pattern', N'Auf der eigenen Infrastruktur von Pattern Blue, niemals auf Plattformen Dritter. Die Daten jedes Unternehmens werden getrennt gespeichert, ohne die M' + NCHAR(246) + N'glichkeit eines Zugriffs von au' + NCHAR(223) + N'en, und die Kommunikation zwischen Ihrem Browser und dem Server wird verschl' + NCHAR(252) + N'sselt ' + NCHAR(252) + N'bertragen.'),
        ('de', 'faq_en_que_idiomas_esta_la_plataforma', N'In welchen Sprachen ist die Plattform verf' + NCHAR(252) + N'gbar?'),
        ('de', 'faq_en_que_se_diferencia_del_eye', N'Worin unterscheidet es sich vom Eye-Tracking per Webcam?'),
        ('de', 'faq_es_una_suite_de_analitica_conductual', N'Es ist eine Verhaltensanalyse-Suite auf Basis von Eye-Tracking. Ein Tobii-Ger' + NCHAR(228) + N't erfasst, wohin Ihr Nutzer beim Verwenden Ihres digitalen Produkts blickt, und die Plattform wandelt diese Daten in Heatmaps, Interessenbereiche, Blickverl' + NCHAR(228) + N'ufe und sofort interpretierbare Aufmerksamkeitskennzahlen um.'),
        ('de', 'faq_escribenos_desde_la_pantalla_de_planes', N'Schreiben Sie uns ' + NCHAR(252) + N'ber den Tarifbildschirm und wir antworten Ihnen in K' + NCHAR(252) + N'rze.'),
        ('de', 'faq_espanol_ingles_y_portugues_cada_usuario', N'Spanisch, Englisch und Portugiesisch. Jeder Benutzer w' + NCHAR(228) + N'hlt seine Sprache in seinem Profil und die Einstellung bleibt zwischen Sitzungen erhalten, ohne den Rest des Teams zu beeinflussen.'),
        ('de', 'faq_falke_usa_hardware_de_infrarrojo_dedicad', N'Falke verwendet dedizierte Infrarot-Hardware, nicht die Webcam des Computers. Das bietet h' + NCHAR(246) + N'here Genauigkeit und wird weder von der Haltung noch von der Beleuchtung des Teilnehmers beeinflusst. Wir setzen au' + NCHAR(223) + N'erdem keine Grenze f' + NCHAR(252) + N'r Dauer oder Asset-Typ: Sie k' + NCHAR(246) + N'nnen ein Videospiel oder einen vollst' + NCHAR(228) + N'ndigen Software-Ablauf analysieren.'),
        ('de', 'faq_hardware_y_soporte', N'Hardware und Support'),
        ('de', 'faq_hay_limite_de_duracion_en_las', N'Gibt es eine Begrenzung der Sitzungsdauer?'),
        ('de', 'faq_ir_a_los_planes', N'Zu den Tarifen'),
        ('de', 'faq_los_datos_de_seguimiento_ocular_se', N'Die Eye-Tracking-Daten werden im Moment des Speicherns von der Identit' + NCHAR(228) + N't des Testers getrennt: Was gespeichert bleibt, erlaubt keine Identifizierung der Person. Dies ist eine Anforderung des Gesetzes Nr. 25.326 zum Schutz personenbezogener Daten und wird bereits beim Entwurf des Systems ber' + NCHAR(252) + N'cksichtigt.'),
        ('de', 'faq_no_el_modelo_de_falke_esta', N'Nein. Das Modell von Falke ist so konzipiert, dass Sie mit Ihren eigenen Nutzern in Ihrer eigenen Umgebung arbeiten. Das bietet deutlich mehr Aussagekraft als ein externes Panel, besonders bei Produkten mit spezifischen Zielgruppen. Wir bieten auch keine Designberatung an: Wir liefern die Belege, die Entscheidung liegt bei Ihrem Team.'),
        ('de', 'faq_no_encontramos_ninguna_pregunta_con_ese', N'Wir haben keine Frage mit diesem Text gefunden. Versuchen Sie es mit anderen W' + NCHAR(246) + N'rtern.'),
        ('de', 'faq_no_puedes_grabar_una_sesion_tan', N'Nein. Sie k' + NCHAR(246) + N'nnen eine Sitzung so lange aufzeichnen, wie Sie ben' + NCHAR(246) + N'tigen, und genau das erm' + NCHAR(246) + N'glicht die Analyse von Videospielen oder vollst' + NCHAR(228) + N'ndigen Abl' + NCHAR(228) + N'ufen betrieblicher Software.'),
        ('de', 'faq_por_que_no_puedo_crear_una', N'Warum kann ich nicht selbst ein Konto erstellen?'),
        ('de', 'faq_porque_el_servicio_incluye_un_dispositiv', N'Weil der Dienst ein physisches Ger' + NCHAR(228) + N't als Leihgabe umfasst. Die Anlage erfolgt durch einen Manager von Pattern Blue nach Vertragsabschluss: Das Unternehmen wird angelegt, der Administrator-Benutzer wird erstellt und diese Person erh' + NCHAR(228) + N'lt eine E-Mail mit einem Link zum Festlegen ihres Passworts. Ab dann l' + NCHAR(228) + N'dt der Administrator den Rest seines Teams ein.'),
        ('de', 'faq_preguntas_frecuentes', N'H' + NCHAR(228) + N'ufig gestellte Fragen'),
        ('de', 'faq_puedo_combinar_varias_sesiones_en_un', N'Kann ich mehrere Sitzungen in einer Analyse kombinieren?'),
        ('de', 'faq_puedo_compartir_los_resultados_con_gente', N'Kann ich die Ergebnisse mit Personen teilen, die kein Konto haben?'),
        ('de', 'faq_que_es_exactamente_falke', N'Was genau ist Falke?'),
        ('de', 'faq_que_necesito_en_mi_equipo', N'Was ben' + NCHAR(246) + N'tige ich auf meinem Computer?'),
        ('de', 'faq_que_pasa_con_los_datos_de', N'Was geschieht mit den Daten der Personen, die teilnehmen?'),
